parameters.jsCode:
const resp = $input.first()?.json || {};
const emails = resp.emails || [];

if (!emails.length) {
  return [];
}

return emails.map(e => ({
  json: {
    ...e,
    dedup_payload: {
      message_id: e.message_id,
      sender: e.sender,
      subject: e.subject,
      received_at: e.received_at
    }
  }
}));

const splitEmail = $('Split Emails')?.item?.json || {};
const custContext = $input.first()?.json || {};
const jevGate = $('Jev Insurance Gate')?.first()?.json || {};

const jevUrgency = jevGate.answers?.urgency_rating?.choice || null;
const urgencyMap = { 'CRITICAL': 5, 'HIGH': 4, 'MEDIUM': 3, 'LOW': 1 };
const score = jevUrgency ? (urgencyMap[jevUrgency] || null) : null;

return [{
  json: {
    email_subject: splitEmail.subject || '',
    email_body: splitEmail.body || '',
    customer_context: custContext,
    jev_priority: jevUrgency,
    jev_urgency_score: score
  }
}];

const splitEmail = $('Split Emails')?.item?.json || {};
const custContext = $('Get Customer Context')?.first()?.json || {};
const triageOutput = $input.first()?.json || {};
const prepInputs = $('Prepare Subworkflow Inputs')?.first()?.json || {};

const payload = {
  message_id: splitEmail.message_id,
  sender: splitEmail.sender,
  subject: splitEmail.subject,
  customer_id: custContext.customer?.id || null,
  policy_number: custContext.policies?.[0]?.policy_number || null,
  claim_number: custContext.claims?.[0]?.claim_number || null,
  category: triageOutput.category || 'General',
  intent: triageOutput.intent || 'GENERAL_QUERY',
  priority: triageOutput.priority || 'Low',
  urgency_score: prepInputs.jev_urgency_score || triageOutput.urgency_score || 1,
  sentiment: triageOutput.sentiment || 'Neutral',
  escalation_needed: triageOutput.escalation_needed || 0,
  summary: triageOutput.summary || '',
  suggested_reply: triageOutput.suggested_reply || '',
  routed_to: triageOutput.routed_to || 'Claims Desk',
  guardrail_status: 'PASSED',
  rejection_reason: null,
  approval_status: 'PENDING',
  reply_status: 'NOT_SENT'
};

return [{
  json: {
    ...triageOutput,
    payload: payload
  }
}];

const subWf = $('Execute Classify & Guardrail SubWf')?.first()?.json || {};
const email = $('Split Emails')?.item?.json || {};
const cust = $('Get Customer Context')?.first()?.json || {};
const logResp = $('Log Pending Triage (Passed Guardrail)')?.first()?.json || {};

const custName = cust.customer?.full_name || 'UNIDENTIFIED SENDER';
const custEmail = email.sender || 'Unknown';
const polNum = cust.policies?.[0]?.policy_number || 'N/A';
const clmNum = cust.claims?.[0]?.claim_number || 'N/A';
const msgId = email.message_id;
const triageRef = String(logResp.id || msgId);

const cardText = `🛡️ *NEW INCOMING INSURANCE TRIAGE (HUMAN REVIEW)*\n` +
`━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n` +
`👤 *Customer:* ${custName} (${custEmail})\n` +
`📄 *Policy:* ${polNum} | 🏷️ *Claim:* ${clmNum}\n\n` +
`🎯 *Intent:* ${subWf.intent || 'UNKNOWN'}\n` +
`📁 *Category:* ${subWf.category || 'General'} | 🚨 *Priority:* ${subWf.priority || 'Medium'} (${subWf.urgency_score || 1}/5)\n` +
`💬 *Sentiment:* ${subWf.sentiment || 'Neutral'} | 🏢 *Desk:* ${subWf.routed_to || 'Support'}\n\n` +
`📝 *Subject:* ${email.subject || 'No Subject'}\n\n` +
`📋 *AI Summary:*\n${subWf.summary || 'No summary provided.'}\n\n` +
`💬 *Suggested Reply (Grounding Verified: ✅ PASSED):*\n\"${subWf.suggested_reply || ''}\"\n\n` +
`━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n` +
`_Review draft carefully. Approve sends reply via SMTP immediately._`;

return [{
  json: {
    message_id: msgId,
    triage_ref: triageRef,
    card_text: cardText
  }
}];

const telResp = $input.first()?.json || {};
const buildCard = $('Build Telegram Card')?.first()?.json || {};
const splitEmail = $('Split Emails')?.item?.json || {};

const telMsgId = telResp.message_id || telResp.result?.message_id;
const telChatId = String(telResp.chat?.id || telResp.result?.chat?.id || $env.TELEGRAM_CHAT_ID || '');
const msgId = buildCard.message_id || splitEmail.message_id;

return [{
  json: {
    message_id: msgId,
    telegram_message_id: telMsgId,
    telegram_chat_id: telChatId
  }
}];

const splitEmail = $('Split Emails')?.item?.json || {};
const custContext = $('Get Customer Context')?.first()?.json || {};
const triageOutput = $input.first()?.json || {};
const prepInputs = $('Prepare Subworkflow Inputs')?.first()?.json || {};

const payload = {
  message_id: splitEmail.message_id,
  sender: splitEmail.sender,
  subject: splitEmail.subject,
  customer_id: custContext.customer?.id || null,
  policy_number: custContext.policies?.[0]?.policy_number || null,
  claim_number: custContext.claims?.[0]?.claim_number || null,
  category: triageOutput.category || 'General',
  intent: triageOutput.intent || 'GENERAL_QUERY',
  priority: triageOutput.priority || 'Low',
  urgency_score: prepInputs.jev_urgency_score || triageOutput.urgency_score || 1,
  sentiment: triageOutput.sentiment || 'Neutral',
  escalation_needed: 1,
  summary: triageOutput.summary || '',
  suggested_reply: '',
  routed_to: triageOutput.routed_to || 'Human Desk',
  guardrail_status: 'REJECTED',
  rejection_reason: triageOutput.rejection_reason || 'Guardrail failed',
  approval_status: 'AUTO_ESCALATED',
  reply_status: 'SUPPRESSED'
};

return [{
  json: {
    ...triageOutput,
    payload: payload
  }
}];

